def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(ax, ay, bx, by):
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_pair(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def valid_xy(x, y):
        return isinstance(x, int) and isinstance(y, int)

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pair(observation.get("self_position", (0, 0)))
    ox, oy = safe_pair(observation.get("opponent_position", (sx, sy)))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(sx, sy, ox, oy)

        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return step_toward(sx, sy, target[0], target[1])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        best = None
        best_dist = None
        for item in targets:
            tx, ty = safe_pair(item, None)
            if tx is None:
                continue
            d = manhattan((sx, sy), (tx, ty))
            if best is None or d < best_dist or (d == best_dist and (tx, ty) < best):
                best = (tx, ty)
                best_dist = d
        if best is not None:
            return step_toward(sx, sy, best[0], best[1])
        if valid_xy(gw, gh) and gw > 0 and gh > 0:
            return step_toward(sx, sy, gw // 2, gh // 2)
        return step_toward(sx, sy, ox, oy)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_dist = None
    for item in resources:
        rx, ry = safe_pair(item, None)
        if rx is None:
            continue
        d = manhattan((sx, sy), (rx, ry))
        if best is None or d < best_dist or (d == best_dist and (rx, ry) < best):
            best = (rx, ry)
            best_dist = d

    if best is not None:
        return step_toward(sx, sy, best[0], best[1])

    if valid_xy(ox, oy):
        if abs(ox - sx) + abs(oy - sy) <= 2:
            return step_toward(sx, sy, sx - (ox - sx), sy - (oy - sy))
        return step_toward(sx, sy, ox, oy)

    return [0, 0]

